SELECT p.* FROM (SELECT f.year_key, f.geography_key, f.product_key, MAX(CASE WHEN t.source_metric_id='5016' THEN f.value END) AS loss_t, count_if(t.source_metric_id='5016') AS present_5016, MAX(CASE WHEN t.source_metric_id='5016' THEN f.observation_key END) AS observation_5016, MAX(CASE WHEN t.source_metric_id='5023' THEN f.value END) AS processed_t, count_if(t.source_metric_id='5023') AS present_5023, MAX(CASE WHEN t.source_metric_id='5023' THEN f.observation_key END) AS observation_5023, MAX(CASE WHEN t.source_metric_id='5071' THEN f.value END) AS stock_variation_t, count_if(t.source_metric_id='5071') AS present_5071, MAX(CASE WHEN t.source_metric_id='5071' THEN f.observation_key END) AS observation_5071, MAX(CASE WHEN t.source_metric_id='5113' THEN f.value END) AS opening_stocks_t, count_if(t.source_metric_id='5113') AS present_5113, MAX(CASE WHEN t.source_metric_id='5113' THEN f.observation_key END) AS observation_5113, MAX(CASE WHEN t.source_metric_id='5141' THEN f.value END) AS food_supply_quantity_t, count_if(t.source_metric_id='5141') AS present_5141, MAX(CASE WHEN t.source_metric_id='5141' THEN f.observation_key END) AS observation_5141, MAX(CASE WHEN t.source_metric_id='5165' THEN f.value END) AS other_uses_t, count_if(t.source_metric_id='5165') AS present_5165, MAX(CASE WHEN t.source_metric_id='5165' THEN f.observation_key END) AS observation_5165, MAX(CASE WHEN t.source_metric_id='5166' THEN f.value END) AS residuals_t, count_if(t.source_metric_id='5166') AS present_5166, MAX(CASE WHEN t.source_metric_id='5166' THEN f.observation_key END) AS observation_5166, MAX(CASE WHEN t.source_metric_id='5510' THEN f.value END) AS production_t, count_if(t.source_metric_id='5510') AS present_5510, MAX(CASE WHEN t.source_metric_id='5510' THEN f.observation_key END) AS observation_5510, MAX(CASE WHEN t.source_metric_id='5520' THEN f.value END) AS feed_t, count_if(t.source_metric_id='5520') AS present_5520, MAX(CASE WHEN t.source_metric_id='5520' THEN f.observation_key END) AS observation_5520, MAX(CASE WHEN t.source_metric_id='5525' THEN f.value END) AS seed_t, count_if(t.source_metric_id='5525') AS present_5525, MAX(CASE WHEN t.source_metric_id='5525' THEN f.observation_key END) AS observation_5525, MAX(CASE WHEN t.source_metric_id='5610' THEN f.value END) AS import_quantity_t, count_if(t.source_metric_id='5610') AS present_5610, MAX(CASE WHEN t.source_metric_id='5610' THEN f.observation_key END) AS observation_5610, MAX(CASE WHEN t.source_metric_id='5910' THEN f.value END) AS export_quantity_t, count_if(t.source_metric_id='5910') AS present_5910, MAX(CASE WHEN t.source_metric_id='5910' THEN f.observation_key END) AS observation_5910 FROM {{fact_fao_sua_observation}} f JOIN {{dim_observation_type}} t ON f.observation_type_key=t.observation_type_key GROUP BY f.year_key, f.geography_key, f.product_key) p
